/** Abstract text + keywords imported from conference PDF (matched by title). */
export type AbstractContent = {
  abstractText: string;
  keywords?: string[];
};

export const abstractContentById: Record<string, AbstractContent> = {
  "d1-a-01": {
    abstractText: `During the COVID-19 pandemic, education systems worldwide experienced an abrupt transition from traditional classroom-based learning to virtual platforms including Sri Lanka also. Online learning was initially introduced as a temporary solution to ensure the continuity of education. However, even in the post-pandemic period, many children continue to demonstrate a preference for online learning over onsite education.This study was conducted among secondary school children in the Elpitiya Divisional Secretariat Division in the Galle District to explore the factors influencing this continued preference. The research specifically examined children’s perceptions, influencing factors, and perceived benefits of online learning compared to onsite learning. A qualitative research design was employed using purposive sampling. Data was collected through semi-structured interviews with 10 children and two focus group discussions involving children aged 11-15 years. The data were analyzed using deductive thematic analysis.The findings revealed that children value online learning for its flexibility, cost-effectiveness, time efficiency and increased accessibility to digital resources compared to the pre-pandemic period. However, participants also reported challenges such as digital fatigue and health-related concerns due to prolonged screen exposure. The study concludes that neither online nor onsite learning is universally superior. The effectiveness of each mode depends on resource availability, pedagogical design and contextual factors. The findings highlight the need to strengthen digital infrastructure in Sri Lanka to reduce educational inequalities`,
    keywords: ["Children", "Online Learning", "Post Covid-19", "Qualitative Study", "Sri Lanka"]
  },
  "d1-a-02": {
    abstractText: `Open and Distance Learning (ODL) has become an important approach to expanding access to higher education by providing flexible and technology-enabled learning opportunities. This study explored the role of ODL in promoting inclusive higher education in Sri Lanka, with a particular focus on the opportunities it offers and the challenges encountered by students and lecturers. A qualitative research approach was adopted using a descriptive research design. Data were collected through semi-structured interviews with 25 purposively selected participants, comprising 20 undergraduate students and five lecturers from different higher education institutions in Sri Lanka. The data were analyzed using thematic analysis. The findings indicate that while ODL has enhanced educational accessibility and flexibility, challenges related to digital infrastructure, internet connectivity, learner engagement, and institutional support continue to affect its inclusiveness. The study highlights the need for strengthened digital infrastructure, enhanced institutional support, and learner- centered online teaching practices to improve the effectiveness of ODL.`,
    keywords: ["Open and Distance Learning", "Inclusive Higher Education", "Digital Education", "Sri Lanka", "Qualitative Research", "Educational Equity"]
  },
  "d1-a-03": {
    abstractText: `The Sri Lankan 2026 Education Reform Agenda has provisioned smart-classroom infrastructure, government-issued devices, and integrated software across all 21 National Colleges of Education (NCOEs), yet the readiness of the human stakeholders expected to operationalize this infrastructure, the “liveware,” remains largely unexamined. This paper reports a research-in-progress mixed-methods study that triangulates two 50-item structured questionnaires (NCOE lecturers and prospective teachers) with focus group discussions (FGDs) among institutional leadership. The lecturer-facing and full scale student instruments, together with the institutional leadership FGDs, are pending administration; a small pilot sample (N = 13) of the prospective-teacher instrument has, however, already surfaced an early signal consistent with the study's central hypothesis: readiness is unevenly distributed across domains, with infrastructural access lagging behind conceptual and pedagogical awareness. The paper outlines the design, current data-collection status, and anticipated triangulated findings once the FGD strand and full-scale survey rollout are completed.`,
    keywords: ["digital readiness", "TPACK", "liveware gap", "teacher education", "mixed-methods research", "SHEL model"]
  },
  "d1-a-04": {
    abstractText: `Government service delivery across Sri Lankan ministries, departments, provincial councils, and statutory bodies remains fragmented and paper-based, relying on physical dockets, manual routing, and limited public visibility, which constrains transparency, accountability, and cross- institution collaboration. This paper presents SCOApp, a unified multi-tenant digital platform designed to digitalize the complete lifecycle of government services, from the first citizen touchpoint through internal workflow processing, letter generation, filing, and final delivery. The platform is built on a single cloud infrastructure with a separate database per organization, ensuring full data isolation, while every form, workflow, role, and rule is configurable through an administrative interface without code modification. A configurable workflow engine, a no code form builder, and a global coordination database together enable multi-hop approval chains that route a single request sequentially across separately governed organizations, illustrated through the educationExpected outcomes include real-time status tracking, full auditability through verifiable electronic signatures, and tri language access in English, Sinhala, and Tamil. The work establishes a transferable foundation for standardized, accountable digital governance.`,
    keywords: ["digital governance", "multi-tenant architecture", "e government services", "workflow automation", "digital transformation", "education administration"]
  },
  "d1-b-01": {
    abstractText: `Generative AI technologies have rapidly transformed higher education by providing students with advanced tools for content generation, academic assistance, and personalized learning experiences. Applications such as ChatGPT are increasingly used by university students for information retrieval, writing support, idea generation, and problem-solving, creating both opportunities and challenges for higher education institutions. While these technologies can enhance learning efficiency and accessibility, concerns have emerged regarding academic integrity, including excessive dependence on AI- generated content, unauthorized assistance during assessments, and reduced independent learning practices. Existing approaches to academic integrity management primarily rely on plagiarism detection systems and manual evaluation methods, which are often reactive rather than preventative. Therefore, there is a growing need for predictive approaches capable of identifying students who may be vulnerable to academic integrity risks. This study proposes a machine learning- based predictive framework for identifying academic integrity risk among undergraduate students in Sri Lankan universities. The framework integrates generative AI usage characteristics, learning behaviour indicators, and academic and digital competency factors as predictive features. Random Forest is proposed as the primary prediction technique due to its robustness and effectiveness in educational prediction tasks . The proposed framework aims to support proactive academic integrity management and responsible AI adoption in higher education.`,
    keywords: ["Academic Integrity", "Generative AI", "Learning Analytics", "Educational Data Mining", "Machine Learning", "Higher Education"]
  },
  "d1-b-02": {
    abstractText: `Generative Artificial Intelligence (GenAI) is transforming programming education by offering students immediate learning support. However, many GenAI tools generate complete code solutions, encouraging superficial learning and overreliance rather than independent problem solving. This study proposes a design for a GenAI-powered Programming Tutor to support personalized learning in higher education. Using a Design Science Research (DSR) approach informed by recent literature, the study identifies key pedagogical and technical requirements for the system. The proposed tutor integrates learner-profile personalization, tiered non-solution-revealing scaffolding, and learning analytics to monitor engagement and progress, adapting support to individual proficiency while promoting independent problem-solving. Expected outcomes include validated architecture and prototypes that improve engagement, task completion, and conceptual understanding, particularly among novice programmers. The study provides practical design guidelines for the responsible integration of GenAI into programming education.`,
    keywords: ["Generative Artificial Intelligence", "Programming Education", "Personalized Learning", "Intelligent Tutoring Systems", "Higher Education", "Learning Analytics"]
  },
  "d1-b-04": {
    abstractText: `Large Language Models are transforming higher education by reshaping teaching, learning, assessment, and academic support. Although their adoption has expanded globally, there is limited empirical evidence on educators' experiences within the Sri Lankan higher education context. This study explores educators' perceptions and experiences of integrating Large Language Models into teaching and learning in a private higher education institution in Sri Lanka. An interpretivist qualitative approach was adopted using semi structured interviews with twelve academics from different disciplines. The data were analysed using Braun and Clarke's six phase thematic analysis. Five themes emerged: Perception of Using Large Language Models, Pedagogical Shift, Academic Integrity, Professional Development, and Future Changes. The findings indicate that educators view Large Language Models as valuable tools for enhancing teaching effectiveness, supporting personalised learning, and improving academic productivity. However, they also identified challenges related to academic integrity, ethical Artificial Intelligence use, educator preparedness, institutional policy, and digital equity. The study highlights the need for pedagogical transformation, assessment redesign, professional development, curriculum reform, and institutional governance to support responsible Artificial Intelligence integration. These findings provide practical guidance for higher education institutions and policymakers seeking to promote ethical, inclusive, and sustainable digital education in Sri Lanka.`,
    keywords: ["Large Language Model", "Artificial Intelligence", "Higher Education", "Pedagogical Shift", "Technology in Higher"]
  },
  "d1-c-02": {
    abstractText: `Content and Language Integrated Learning (CLIL) is recognised as an effective pedagogy for integrating disciplinary content with L2 development. With increasing AI integration in higher education, AI-assisted CLIL offers new possibilities. This study investigated the effectiveness of AI -assisted CLIL in improving th e L2 proficiency of second-year Tamil-medium Social Sciences undergraduates at the University of Jaffna, Sri Lanka. A one-group quasi- experimental mixed-methods design was employed with 34 participants over one semester. Data were collected from a pretest and posttest measuring reading and writing skills, and semi -structured interviews exploring learners’ perceptions and experiences of the intervention. Throughout the study, participants engaged with subject -related English texts and tasks while using AI to ols, like ChatGPT and Gemini to support content development, and text comprehension, along with weekly presentations. Quantitative analysis revealed significant improvement in students’ performance. Qualitative findings indicated that participants perceived AI-assisted CLIL as conducive to independent learning. Participants reported increased confidence, improved ability to access and understand materials in English, and greater reliance on AI tools for learning. Thus, the findings suggest that AI -assisted CLIL is an effective pedagogical approach for promoting English language development while supporting disciplinary knowledge and learner autonomy provided that students receive Critical AI Literacy training.`,
    keywords: ["AI-assisted CLIL (AICLIL)", "AI in Education", "Critical AI Literacy", "Self-directed Learning", "Tertiary Level"]
  },
  "d1-c-03": {
    abstractText: `Hybrid higher education has expanded access through video conferencing platforms, learning management systems, recorded lectures, discussion boards, and digital assessment, yet access does not always produce meaningful participation. This completed qualitative study examined digital silence among 15 undergraduate students in Sri Lankan higher education across one 16-week semester. Data were collected through an open-ended questionnaire and semi- structured interviews and analysed thematically. The findings show that digital silence is not a single form of disengagement but a continuum ranging from engaged invisibility to silent withdrawal. Five forms emerged: reflective, protective, access-based, design-induced, and withdrawal silence. The study identifies the visibility-pressure paradox, hybrid in-betweenness, and layered participation. A mini case study of one redesigned module shows how a teacher moved from a camera-on mandate to layered, low-pressure participation; this case informed the diagnostic pedagogical framework and its LISTEN response set. Given the small purposive sample, the findings are analytically rather than statistically generalisable. The study contributes to online pedagogy, learner engagement, access, inclusion, and quality assurance in digital education.`,
    keywords: ["digital silence", "hybrid higher education", "learner engagement", "online pedagogy", "digital inclusion", "quality assurance"]
  },
  "d1-c-05": {
    abstractText: `Open and Distance Learning (ODL) environments provide flexible learning opportunities; however, sustaining learner engagement remains a critical challenge due to increased dependence on learner autonomy, digital platforms, and self-management skills. This study investigates the behavioural factors influencing learner engagement decay among undergraduate students in an ODL context, focusing on students at the Open University of Sri Lanka (OUSL). A quantitative cross- sectional survey design was adopted, and data were collected from 236 undergraduate students representing Information Technology (IT), Science, and Engineering degree programmes using a structured questionnaire based on a five-point Likert scale. The study examined five key constructs: Learning Management System (LMS) learning behaviour, notification-driven learning, social media learning influence, self-regulated learning, and engagement decay. Data were analysed using IBM SPSS Statistics software through reliability analysis, descriptive statistics, Pearson correlation, independent samples t-tests, and one-way ANOVA. The findings revealed that notification driven learning had the strongest positive association with engagement decay (r = .650, p < .001), whereas LMS learning behaviour and self-regulated learning demonstrated significant negative relationships with engagement decay. Significant differences were also identified based on gender, study programme, weekly study hours, and employment status. The findings highlight the importance of promoting self-regulated learning, meaningful LMS engagement, and adaptive digital support mechanisms to reduce learner disengagement and improve persistence in ODL environments.`,
    keywords: ["Open and Distance Learning", "Learner Engagement Decay", "Self-Regulated Learning", "Learning Management Systems", "Digital Learning Behaviour"]
  },
  "d1-c-06": {
    abstractText: `Digital education has become a key component of educational transformation worldwide, particularly following the rapid integration of digital technologies into teaching and learning environment. In Sri Lanka, digital education is fast growing field and increasing attention due to advancement in information and communication technology (ICT). This study aims to examine the trends and patterns of the publications, influential authors and leading sources of digital education in Sri Lanka through this bibliometric analysis. This analysis was conducted using research publications retrieved from the OpenAlex database covering the period of 2015-2026. The bibliographic data were analyzed using Biblioshiny interface. The analysis identifies 459 publications distributed across 200 sources and authored by 1095 researchers. Citation analysis indicated that publications from 2019-2020 received highest average citations reflecting their significant scholarly influence. The findings demonstrate the growing importance of digital education research in Sri Lanka while highlighting research priorities and collaboration patterns.`,
    keywords: ["Bibliometric", "Biblioshiny", "Digital Education", "OpenAlex", "Sri Lanka"]
  },
  "d1-d-01": {
    abstractText: `Artificial Intelligence (AI) is increasingly influencing classroom practice by supporting lesson planning, instructional design, assessment, and personalised learning. However, effective integration of AI is associated with teachers' AI literacy and their ability to apply AI appropriately in educational contexts. This study examined AI literacy and pedagogical use of AI among Sri Lankan school teachers and explored the relationship between these two constructs. A quantitative survey design was employed using a structured online questionnaire distributed through non-probability snowball sampling. Data were collected from 410 school teachers representing 25 districts and Sinhala, Tamil, and English medium schools across Sri Lanka. Descriptive statistics and Pearson's correlation analysis were used to analyse the data. The findings revealed that ChatGPT and Gemini were the most frequently used AI tools, while specialised educational AI applications showed limited adoption. Teachers demonstrated moderately high AI literacy but only moderate levels of pedagogical use. Significant positive relationships were found between all dimensions of AI literacy and pedagogical use, with AI Use and Application showing the strongest association with pedagogical application (r = .737, p < .01). The findings highlight the importance of strengthening teachers' AI literacy to promote effective and responsible integration of AI into classroom practice.`,
    keywords: ["Artificial intelligence", "AI literacy", "pedagogical use", "school teachers", "digital education", "Sri Lanka"]
  },
  "d1-d-04": {
    abstractText: `Artificial Intelligence (AI) is becoming an increasingly important part of fashion design, extending the industry's digital transformation from production and planning into creative design activities. While existing research has largely focused on the capabilities and applications of AI, less attention has been paid to how designers adapt to these technologies and incorporate them into their everyday creative practice. This narrative literature review explores designer adaptation to AI in fashion design, with particular emphasis on learning, skill development, and technology acceptance. An initial review of approximately fifty publications was undertaken, from which sixteen key studies were selected based on their relevance to Designer’s AL adaptation, and fashion design practice. The review shows that AI adoption is part of a gradual evolution from CAD-enabled workflows to AI-supported creative environments. It further highlights that successful AI integration depends not only on technological advances but also on designers' ability to develop new competencies, adapt their creative workflows, and collaborate effectively with AI, positioning Human-AI co-creativity as an important direction for future research`,
    keywords: ["Digital transformation", "Artificial Intelligence (AI)", "Fashion Design Practice", "Designer Adaptation and Human-AI Co-Creativity"]
  },
  "d1-d-05": {
    abstractText: `Information and Communication Technology education in Sri Lanka is constrained by a persistent urban rural digital divide, limited mother tongue learning support, and weak alignment between global platforms and the national curriculum. This study presents the design of an artificial intelligence driven adaptive learning platform integrating personalised learning paths, multilingual intelligent tutoring, learning analytics, and offline first delivery to improve ICT outcomes for Sri Lankan school students. Adopting a design science approach, the study conducts a structured market gap analysis of seven platforms, derives a taxonomy of twenty five features and ten novel research grade capabilities, and proposes a modular architecture combining knowledge tracing, fairness aware modelling, and natural language processing in Sinhala, Tamil, and English. Expected outcomes include earlier detection of knowledge gaps, more equitable performance benchmarking, and improved engagement among under resourced learners. The work contributes a context sensitive framework for applying artificial intelligence in open and digital education within a developing country setting. Index Terms-AI in education, adaptive learning, learning analytics, intelligent tutoring systems, digital divide, ICT education.`,
  },
  "d1-d-06": {
    abstractText: `The increasing demand for data-literate graduates has highlighted the need for authentic, industry relevant learning experiences. However, access to real-world financial market data for education remains constrained by commercial, legal, and governance considerations. This paper proposes Financial Market Data Access Architecture (FMDAA), a governance-informed three-tier architecture for improving educational access to financial market data through publicly available datasets, managed institutional access, and secure educational sandbox environments. The study adopts a Design-Based Research (DBR) approach informed by practitioner expertise, a review of Open Educational Resources (OER) and data science education literature, and a landscape analysis of financial data access models. The proposed architecture aims to improve data literacy, support authentic data-driven learning, and strengthen industry-academia collaboration while balancing educational accessibility with commercial, technical, and governance requirements. If validated, FMDAA could provide a scalable model for integrating authentic financial market data into Open and Distance Learning (ODL) and other data-intensive educational contexts.`,
    keywords: ["Open Educational Resources (OER)", "Financial Market Data", "Data Literacy", "Open and Distance Learning", "Design-Based Research", "Data Governance"]
  },
  "d1-e-01": {
    abstractText: `Despite the widespread integration of digital tools, a critical need exists for an effective digital teaching and learning process that goes beyond simple technology adoption to enhance pedagogical outcomes. In this study, conceptual design methodology was used to design a novel synergistic digital teaching and learning process in which teaching and learning process is grounded in three foundational pillars; microlearning (ML), connective alignment (CA), and universal design for learning (UDL). ML was incorporated to improve academic performance and enhance learning engagement. CA was incorporated to promote informal learning, lifelong learning and emergent learning- key areas that are often lacking in the widely adopted educational approach of constructive alignment. UDL was incorporated to promote equity and inclusion. Hence, amalgamation of ML, CA and UDL is proposed to obtain a synergistic effect on teaching and learning. This study offers practical implications for educators and policymakers in higher education to foster an effective digital teaching and learning process.`,
    keywords: ["Digital transformation", "online learning", "microlearning", "connective alignment", "universal design for learning"]
  },
  "d1-e-02": {
    abstractText: `The university campus has become an indispensable context in which to teach and learn, but it is often seen as a passive arena in which to teach rather than a tool that facilitates blended learning. This extended abstract suggests an integrated framework in which to design the spaces and facilities for the operational and pedagogical needs for hybrid learning environments within higher education. This paper brings together the recent literature on the design of learning spaces, the use of hybrid classroom technologies and space governance through facilities management and recognises common disconnects between the strategic vision for technology-enhanced learning spaces that are flexible and the practical challenges of room scheduling, occupancy and cross unit coordination. It describes a conceptual approach that connects three interdependent layers: one on spatial configuration, one on technological infrastructure and one on facilities management decision making, by continuously monitoring the occupancy and the utilisation of space. The paper suggests that, if spatial and technological standards are early established in the campus development process, the gap between planned flexibility and actual use can be closed best by facilities managers rather by architects or information technology staff only. Potential contributions include a blueprint for how to implement an optimisation process within a facilities-management context for hybrid spaces, and implications for campus planning, teaching practice, and future research into data-driven space governance in an open and digital education environment.`,
    keywords: ["hybrid learning spaces", "facilities management", "spatial design", "smart campus", "higher education", "space utilisation"]
  },
  "d1-e-03": {
    abstractText: `Chemistry education at the General Certificate of Education Advanced Level depends on safe, well-organized laboratories that enable students to connect theoretical knowledge with practical inquiry. In several schools in the Valikamam Educational Zone of Jaffna, however, laboratory management problems, expired chemicals, inadequate ventilation, limited waste-disposal arrangements, and restricted access to practical work may reduce learning opportunities and create environmental and safety concerns. This study examined teachers’ and students’ perceptions of laboratory organization and its perceived effects on the school environment using survey data from 15 chemistry teachers and 244 students across 16 1AB schools. Descriptive statistics, one-way analysis of variance, correlation, and simple linear regression were used to analyses the responses. The teacher model indicated a strong relationship between laboratory disorganization and perceived negative environmental effects, whereas the student model explained very little variance, revealing a substantial difference in stakeholder perceptions. Based on these findings, the paper proposes virtual laboratories and AI-supported simulations as complementary tools for hazardous, costly, or inaccessible experiments. Their effectiveness should be evaluated through future pilot studies assessing learning achievement, practical competence, usability, teacher readiness, and infrastructure requirements.`,
    keywords: ["Chemistry education", "laboratory safety", "virtual laboratories", "artificial intelligence", "digital learning", "Jaffna"]
  },
  "d1-e-04": {
    abstractText: `Embedded machine learning and hardware software co-design are core engineering competencies, yet they are difficult to teach at a distance because they demand hands on contact with real hardware. Open and distance learners seldom have sustained laboratory access. Remote and virtual laboratories partly close the gap, but they are institution-hosted and not owned by the learner; pure simulation removes the moment of confirming a design on real silicon. This paper presents a design-based study of an open, low-cost (≈US$130) field-programmable gate array (FPGA) learning resource that a distance learner can build, operate, and formally verify on their owndesk. A network trained in PyTorch is exported to fixed-point arithmetic, synthesised to register-transfer level (RTL) hardware, and demonstrated on natural images and electrocardiogram signals. Its defining feature is bit-exact verifiability: an on device self-test proves that the learner’s hardware reproduces the software model exactly, turning correctness from a claim into a checkable learning outcome. Index Terms-open and distance learning, educational hard ware, FPGA, embedded machine learning, remote laboratories, open educational resources, design-based research, reproducibility.`,
  },
  "d1-e-05": {
    abstractText: `In many developing countries, including Sri Lanka, concerns persist regarding the alignment between education and contemporary industry expectations. So, as in fashion education, despite the growing digitalization of the apparel sector, there is limited empirical evidence on how industry professionals themselves developed digital competencies and on what educational experiences shaped their professional journeys in the fashion design professions. Understanding these experiences is particularly important for informing digital transformation initiatives in fashion education and identifying the need for digital integration into the formal curriculum. This article presents findings derived from ten in-depth interviews with fashion design industry professionals employed in the Sri Lankan export apparel industry. The Sri Lankan export apparel industry encompasses the country's garment manufacturing and apparel export sectors and designs, develops, manufactures, and exports clothing products for international markets. The findings indicate participants’ digital learning journeys, experiences with technology adoption, perceptions of current educational practices, and recommendations for the future integration of digital elements into fashion design education. The digital learning journey represents the evolving process through which fashion professionals develop their knowledge, skills, and attitudes to effectively adopt and utilize digital technologies throughout their educational and professional practice.`,
    keywords: ["Fashion design education", "Digital competencies", "Digital learning journey", "Apparel industry", "Sri Lanka."]
  },
  "d1-f-01": {
    abstractText: `EdTech platforms increasingly rely on granular learner engagement metrics to improve pedagogy, yet the same data infrastructure can become an invasive surveillance apparatus if left ungoverned. This paper evaluates the ethical and legal boundaries of student data analytics and proposes a four-principle governance model for learning analytics in open and digital education contexts. Drawing on FERPA, GDPR, recent regulatory enforcement actions, and empirical research on surveillance harms, the paper argues that robust governance should rest on transparent purpose specification, staged and meaningful consent, data minimization with defined retention limits, and algorithmic accountability. The model treats governance as permanent institutional infrastructure rather than a narrow compliance exercise and positions student data literacy as a pedagogical outcome. It further proposes a governance model intended to be adaptable across legal regimes and resource contexts, including institutions in the Global South.`,
    keywords: ["learning analytics", "student data privacy", "EdTech governance", "GDPR", "FERPA", "algorithmic accountability"]
  },
  "d1-f-03": {
    abstractText: `Each year, only about one in four Sri Lankan Advanced Level candidates secure a state university place, and admitted students then face a six to twelve month gap before inauguration with no structured guidance on curriculum, career outcomes, or salary expectations. This gap is felt most acutely by students in under-resourced districts who lack access to informal advisory networks available to peers in urban centres. This study proposes an AI-assisted guidance platform that integrates five years of University Grants Commission admission cut-off data, national labour market statistics, and a purpose-built graduate outcomes survey to support course selection and preparation. Rather than presenting a statistically unsupported admission probability, the system computes a historical eligibility trend from published cut-off data, while natural language processing and generative AI are applied to extract labour market signals and produce personalised guidance reports. Preliminary work has validated automated extraction of admission records with two hundred and sixty one verified university course combinations. The platform is expected to demonstrate that transparent, data grounded decision support can improve equitable access to higher education guidance in a resource constrained national context.`,
    keywords: ["AI in education", "career guidance", "university admission", "equitable access", "labour market alignment", "decision support"]
  },
  "d1-f-04": {
    abstractText: `Open and Distance Learning (ODL) has become an important approach to expanding access to higher education by providing flexible and technology-enabled learning opportunities. This study explored the role of ODL in promoting inclusive higher education in Sri Lanka, with a particular focus on the opportunities it offers and the challenges encountered by students and lecturers. A qualitative research approach was adopted using a descriptive research design. Data were collected through semi-structured interviews with 25 purposively selected participants, comprising 20 undergraduate students and five lecturers from different higher education institutions in Sri Lanka. The data were analyzed using thematic analysis. The findings indicate that while ODL has enhanced educational accessibility and flexibility, challenges related to digital infrastructure, internet connectivity, learner engagement, and institutional support continue to affect its inclusiveness. The study highlights the need for strengthened digital infrastructure, enhanced institutional support, and learner- centered online teaching practices to improve the effectiveness of ODL.`,
    keywords: ["Open and Distance Learning", "Inclusive Higher Education", "Digital Education", "Sri Lanka", "Qualitative Research", "Educational Equity"]
  },
  "d1-f-05": {
    abstractText: `This study investigates higher education marketing mix perceptions among school leavers across five Sri Lankan districts (Matale, Monaragala, Badulla, Kegalla, and Anuradhapura), using the 7Ps framework adapted to an Open and Distance Learning (ODL) context. A cross-sectional survey of 215 school leavers was analysed using Principal Component Analysis (PCA), Cronbach's alpha, and one-way ANOVA. Results revealed a six-factor structure in which the traditional Price dimension split into Payment Flexibility and Cost Affordability, while Product, Promotion, and Place converged into centre-mediated constructs. Staff Support and Cost Affordability were rated highest; Physical Environment and Accessibility was rated lowest. District of residence, rather than raw geographic distance, was the strongest predictor of perceptual differences, while gender showed no significant effect. Findings suggest that ODL marketing strategies should be district-sensitive, prioritising payment flexibility, affordability, and regional-centre infrastructure.`,
    keywords: ["higher education marketing", "7Ps framework", "open and distance learning", "school leavers", "Sri Lanka", "factor analysis"]
  },
  "d1-g-01": {
    abstractText: `In Sri Lanka, many students enrolled in technology related undergraduate degree programs have not formally studied mathematics since completing the G.C.E. Ordinary Level examination. Consequently, students may experience difficulties with the mathematical concepts required for undergraduate level studies. To bridge this gap, a Pre- Mathematics Orientation program was introduced for the 2023 technology batch. This study examined the effectiveness of the program on first year academic performance using quizzes and mid exam scores from students enrolled in Computing Technology (CT) and Engineering Technology (ET) degree programs. This study analyzes a comparative study across the province, age, and gender-wise. A total of 385 students were analyzed, including 190 from the 2023 batch who participated in the orientation program and 195 from the 2024 batch for whom the program was not conducted. Independent samples t tests, two-way analysis of variance (ANOVA), and Kruskal Wallis tests were performed across gender, province, and age subgroups using R. Students who participated in the Pre Mathematics Orientation Program generally performed better than those who did not. Overall, the findings indicate that the orientation program had a positive impact on undergraduate academic performance.`,
    keywords: ["ANOVA", "t-tests", "Kruskal-Wallis test"]
  },
  "d1-g-02": {
    abstractText: `Learning Management Systems (LMSs) play a central role in digital higher education, yet maintaining learner engagement and motivation remains a persistent challenge. Conventional gamification typically applies identical game mechanics to all learners, limiting its ability to accommodate differences in learning behaviour, academic performance, and motivation. This study proposes the Adaptive Gamification Framework (AGF), a conceptual decision framework that transforms static gamification into an adaptive, learner-centred approach for personalised learning. The framework was developed using a Design Science Research methodology supported by a structured synthesis of contemporary literature on gamification, learning analytics, learner modelling, adaptive educational technologies, and personalised learning. AGF integrates learner behaviour, performance, and motivation through learning analytics, dynamic learner modelling, an adaptive decision engine, and an adaptive gamification engine to generate context-aware motivational strategies within LMSs. The framework further incorporates governance considerations, continuous learner feedback, and progressive profile refinement to support transparent and adaptable educational decision-making. The proposed AGF contributes a reusable conceptual reference model for designing intelligent learning management systems and establishes a theoretical foundation for future implementation and empirical evaluation in higher education.`,
    keywords: ["Adaptive gamification", "Learning Management Systems", "Personalized learning", "Learning analytics", "Learner modelling", "Intelligent education."]
  },
  "d1-g-03": {
    abstractText: `Asynchronous learning provides flexibility and ac cessibility, particularly for working adults and students managing multiple responsibilities. However, limited real-time interaction may affect engagement, academic guidance, confidence, and self regulated learning. The Bachelor of Information Technology ex ternal degree programme at the University of Moratuwa primar ily uses asynchronous delivery through Moodle. To strengthen learner support, fortnightly Tutor-Mentor Sessions were intro duced in 2024 for Semester 1 and Semester 2 students. This study examines students’ perceptions of the sessions and identifies the features they consider most valuable. A survey of 293 students from 847 eligible participants (34.6% response rate) showed that all respondents rated the sessions as either Helpful or Very Helpful. Academic guidance was the most valued aspect, followed by study skills and time-management support and opportunities to ask questions. The findings indicate that students perceive structured synchronous support as a valuable complement to asynchronous learning by providing guidance and interaction that self-paced resources alone may not fully provide.`,
    keywords: ["Asynchronous learning", "distance learning", "tutor mentor sessions", "student engagement", "academic guidance", "learner support"]
  },
  "d1-g-04": {
    abstractText: `The global educational landscape is undergoing a massive shift driven by big data and machine learning. Within the Sustainable Development Goal 4 (SDG 4) framework, Artificial Intelligence (AI) serves as a vital tool to bridge the digital divide. However, current policies often ignore the realities of developing nations. This study evaluates how AI can be integrated into resource-constrained environments to address systemic inequalities. Using a systematic review of international case studies and digital competency frameworks, this paper explores the transformation of educational management and pedagogy. The analysis proposes a multi-stakeholder governance model and an AI Observatory to mitigate the digital divide in developing economies. By synthesizing cutting-edge empirical findings from late 2024, this document argues that sustainable implementation requires a shift from reactive, palliative responses toward anticipatory national strategies that address teacher self-efficacy and ethical data governance.`,
    keywords: ["Digital transformation", "online learning", "AI in education", "global policy", "frugal innovation", "digital equity."]
  },
  "d1-h-01": {
    abstractText: `Student performance shows significant variability in the higher education context. Early forecasting of Grade Point Average (GPA) will help identify students who are performing well and those who are struggling academically, which would facilitate the provision of additional assistance for these students. Existing frameworks for determining the earliest prediction semester mainly focus on model accuracy which ignores the prediction stability and systematic bias toward students at the lower tails of the distribution. Using data on undergraduate students from a Sri Lankan State University from 2017 to 2019, this research provides a novel three-criterion reliability framework that addresses prediction accuracy, prediction stability, and group-level directional bias. Results indicate that the point at which predictions become reliably actionable varies meaningfully across student performance groups, driven primarily by convergence of directional bias and reductions in Root Mean Squared Error (RMSE) variability. The proposed methodology is transferable across institutional settings and explicitly accounts for student heterogeneity, providing a structured basis for responsible, equity-aware academic intervention.`,
    keywords: ["GPA prediction", "education analytics", "prediction reliability", "algorithmic bias in education", "prediction stability", "higher education"]
  },
  "d1-h-02": {
    abstractText: `The expansion of Open and Distance Learning (ODL) has widened access to higher education, yet intensified the challenge of verifying candidate identity in physically supervised examinations. At the University of Moratuwa’s Center for Open and Distance Learning (CODL), the Bachelor of Information Technology program admits large cohorts who are strangers to invigilating staff, exposing assessments to impersonation, while manual identity-card checks against printed rosters are slow and hard to audit. This paper reports the design and deployment of Verifica, a bespoke ecosystem pairing low-cost portable fingerprint hardware built on the ESP32 microcontroller with a centralized cloud matching service and a real-time web dashboard. It enforces identity, module eligibility, and laboratory allocation at entry and replaces paper rosters with immutable digital logs. Deployment cut per-unit hardware cost by over eighty percent, removed device-level enrollment ceilings, and eliminated proxy candidate fraud, demonstrating that scalable, affordable identity assurance is achievable for high-volume ODL assessment.`,
    keywords: ["Academic integrity", "biometric authentication", "open and distance learning", "examination administration", "digital trans formation", "scalable assessment"]
  },
  "d1-h-03": {
    abstractText: `This study examines the influence of artificial intelli gence (AI)-enhanced YouTube features on the academic outcomes of undergraduate students in Sri Lanka. The study focuses on four key AI-driven features: personalized content recom mendations, AI-assisted content quality, AI-generated subtitles and transcripts, and automatic video chapters and summaries. A quantitative research approach was adopted, and data were collected through a structured questionnaire distributed among undergraduate students who use YouTube for academic learning. The collected data were analyzed using Partial Least Squares Structural Equation Modeling (PLS- SEM) to evaluate the rela tionships between AI-enhanced features and academic outcomes. The findings reveal that personalized content recommendations and automatic video chapters and summaries have a significant positive influence on students’ academic outcomes,while AI assisted content quality and AI-generated subtitles and tran scripts do not show significant effects. The study highlights the importance of AI-supported functionalities in improving digital learning experiences and provides valuable insights for educators and higher education institutions to effectively integrate AI enabled learning platforms`,
    keywords: ["Artificial Intelligence", "YouTube", "AI-Enhanced Learning", "Academic Outcomes", "Higher Education."]
  },
  "d1-h-04": {
    abstractText: `Practical experience with real-world computing environments is essential for effective learning in software engineering and computational disciplines. However, universities often lack scalable and institutionally governed platforms that support hands-on development while maintaining academic supervision, security, and resource control. Existing approaches based on personal devices, shared computing systems, or external cloud services introduce challenges related to cost, data ownership, operational management, and institutional oversight. This paper presents Pre-Production Sandbox Environment (PreProd SE), a governance-aware academic cloud platform based on a hybrid Platform-as-a-Service (PaaS) and Software-as-a-Service (SaaS) architecture for supervised digital learning and computational research. The platform integrates containerised execution, automated deployment workflows, and supervisor-aware governance within institutionally managed infrastructure, enabling students to engage in deployment-oriented learning while maintaining institutional control and visibility. A functional prototype of PreProd SE was deployed in a controlled academic environment involving approximately 20 students and supervisors. Observations from this pilot indicate support for concurrent isolated workloads, automated deployment workflows, controlled resource allocation, and improved supervisory visibility. While formal performance benchmarking and structured user studies were not conducted, the results provide initial evidence of feasibility within a real-world educational context. The findings suggest that PreProd SE provides a practical approach for bridging the gap between theoretical instruction and real-world software engineering practice by integrating cloud-native development workflows with academic governance mechanisms into digital education systems.`,
    keywords: ["Academic cloud computing", "Computing education", "Containerisation", "DevOps", "Platform- as-a-Service", "Sandbox environments", "Software-as-a-Service."]
  },
  "d1-p-01": {
    abstractText: `In Higher Education, undergraduate students have increasingly been leveraging Generative Artificial Intelligence (GenAI) tools, including ChatGPT, Microsoft Copilot, and Google Gemini, to aid in their academic writing. These tools support students in brainstorming, grammar checking, paraphrasing, and organizing academic text, enhancing their writing skills and self-assurance. There have, however, been questions about excessive reliance on AI, a lack of critical thinking and originality, and issues with academic integrity. The research examines the influence of Generative AI on the academic writing of undergraduate students, highlighting the opportunities and challenges posed by GAs. A quantitative descriptive research design is recommended, and data will be collected using an online questionnaire administered to undergraduate students. The study explores AI usage patterns, its impact on writing abilities, and the challenges it presents. Some potential outcomes involve increased independent thinking, better grammar, vocabulary, and more writing efficiency, but also greater reliance on generated content and less independent thinking. The study underscores the critical need for AI literacy, ethical frameworks, and policy creation within the university environment to facilitate the responsible application of Generative AI in academic communication.`,
    keywords: ["Generative AI", "higher education", "academic writing", "AI literacy", "student learning", "digital education."]
  },
  "d1-p-02": {
    abstractText: `Personalized learning has become increasingly im portant in modern education, yet many existing tutor matching systems do not adequately consider individual learning prefer ences when recommending tutors. This study presents a data sci ence approach for classifying self-reported learning preferences expressed in natural language from textual learning requirements to support more effective tutor-student matching. The aim was to construct a model which would be able to automatically recognize preferred learning style of a person based on provided text. For this purpose, a Visual-Auditory-Kinesthetic (VAK) dataset with around 15,000 labeled examples of texts was used. Data pre processing phase consisted of text normalization, tokenization, stop-word removal and stemming by using natural language processing methods in order to ensure high quality of texts. Feature extraction was done with the help of term frequency- inverse document frequency technique (TF-IDF), while Naive Bayes Classifier was used for multi-class classification of learning styles. Trained model was incorporated into a web application which will analyze provided learning preferences of users at the moment of their registration and suggest appropriate learning style category. Based on the predictions, tutor recommendation became more personalized. Experimental results demonstrated that the accuracy reached about 95% Index Terms-Personalized Learning, Tutor Matching, Ma chine Learning, Natural Language Processing, Learning Style Prediction, Digital Education`,
  },
  "d1-p-03": {
    abstractText: `This study examines the impact of e learning on soft skills development among Sri Lankan management undergraduates within the context of digital education. As higher education adopts online and blended learning, it is important to examine whether e-learning contributes to essential soft skills such as communication, collaboration, time management, and independent learning. However, limited empirical evidence exists regarding how e-learning contributes to soft skills development among Sri Lankan management undergraduates. A quantitative research design was employed, and primary data were collected from ninety-nine valid responses using a structured questionnaire. Data analysis was conducted using reliability testing, descriptive statistics, Pearson correlation, and simple linear regression. The findings indicate that students generally perceive e learning positively and believe that it supports the development of soft skills. The results further reveal a significant positive relationship between e learning and soft skills development, while regression analysis confirms that e learning is a significant predictor of soft skills development. The study highlights the importance of well designed e learning environments in enhancing student capabilities and supporting effective digital education practices in Sri Lanka.`,
    keywords: ["E learning", "soft skills development", "management undergraduates", "digital education", "Sri Lanka"]
  },
  "d1-p-04": {
    abstractText: `This study intentions to investigate factors that affect students' accessibility to online education among undergraduate students in Sri Lanka. The dependent factors are internet quality, device availability, data affordability, electricity reliability, and digital literacy. This research used a quantitative and cross-sectional online survey method by 392 sampling of undergraduates at SLIATE Ratnapura by using non-probability convenience sampling method. It was measured using a structured five-point Likert scale of questionnaire. Reliability, descriptive statistic, Pearson’s coefficient, and multiple regressions are applied in the analysis. Multiple linear regression model shows a significant model which explains 67.9% of the variance in the students’ accessibility towards online learning. The device availability had the most prominent impact followed by digital literacy, internet quality, electricity reliability, and data affordability respectively. But internet quality explained a significant negative coefficient effect in the regression model and re estimated the model with increasing the sample size had resulted in highly significant positive coefficient for internet quality.`,
    keywords: ["Online Education", "Access Barriers", "Internet Quality", "Device Availability", "Digital Literacy", "Sri Lanka"]
  },
  "d1-p-05": {
    abstractText: `Access to education serves as a crucial factor in social mobility. Individuals leaving mainstream education become vulnerable NEET individuals. This study explored whether vocational orientation was facilitated within the context of Open School for disadvantaged groups in Sri Lanka. This research uses convergent mixed-methods, and quantitative data were gathered from 70 learners using structured surveys, alongside qualitative insights from 7 educators and coordinators. Statistical analysis was conducted using RStudio to compute descriptive statistics, frequency distributions, and chi-square tests, complemented by qualitative analysis using Braun and Clarke's thematic analysis. The results, generated through both quantitative data analysis using statistical methods and qualitative data analysis via theme generation, revealed a considerable lack of career awareness, where more than 70% of learners failed to know of any career guidance facilities available, while just 28.5% of learners enrolled in technical and vocational education and training programs due to economic, geographical, and institutional barriers. Perhaps most importantly, 64.3% were engaged in digital career guidance. The findings of the research suggest that transitioning from a fragmented approach to an integrated one, incorporating digital career guidance, would greatly enhance career readiness and inclusiveness.`,
    keywords: ["Open schooling", "vocational orientation", "digital career guidance", "inclusive education", "non- formal learning."]
  },
};

